import {ARENA,BONUS} from './engine.js';
const cube=new T.BoxGeometry(1,1,1),sphere=new T.SphereGeometry(1,12,9),cylinder=new T.CylinderGeometry(1,1,1,16),cone=new T.ConeGeometry(1,1,12),mats=new Map();
function mat(c){if(!mats.has(c))mats.set(c,new T.MeshStandardMaterial({color:c,roughness:.8}));return mats.get(c);}
function mesh(parent,geo,c,x,y,z,sx,sy,sz){const o=new T.Mesh(geo,typeof c==='number'?mat(c):c);o.position.set(x,y,z);o.scale.set(sx,sy,sz);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o;}
const ball=(p,c,x,y,z,a,b,d)=>mesh(p,sphere,c,x,y,z,a,b,d),box=(p,c,x,y,z,a,b,d)=>mesh(p,cube,c,x,y,z,a,b,d);
function label(text,color,w=1){const canvas=document.createElement('canvas');canvas.width=256;canvas.height=128;const q=canvas.getContext('2d');q.fillStyle='#fff9e6';q.beginPath();q.roundRect(6,12,244,104,32);q.fill();q.fillStyle=color;q.font='bold 65px sans-serif';q.textAlign='center';q.textBaseline='middle';q.fillText(text,128,67);const tex=new T.CanvasTexture(canvas);tex.colorSpace=T.SRGBColorSpace;const s=new T.Sprite(new T.SpriteMaterial({map:tex,depthWrite:false}));s.scale.set(w,w*.5,1);return s;}
function batch(parent){parent.updateMatrixWorld(true);const sets=new Map();parent.traverse(o=>{if(!o.isMesh||o.material.transparent)return;const k=o.geometry.uuid+o.material.uuid;if(!sets.has(k))sets.set(k,[]);sets.get(k).push(o);});for(const list of sets.values()){if(list.length<3)continue;const m=new T.InstancedMesh(list[0].geometry,list[0].material,list.length);list.forEach((o,i)=>m.setMatrixAt(i,o.matrixWorld));m.castShadow=true;m.receiveShadow=true;list.forEach(o=>o.parent.remove(o));parent.add(m);}}
export class HuntWorld{
 constructor(canvas){this.canvas=canvas;this.compact=matchMedia('(max-width:850px),(pointer:coarse)').matches;this.renderer=new T.WebGLRenderer({canvas,antialias:true,powerPreference:'high-performance'});this.renderer.setPixelRatio(Math.min(devicePixelRatio||1,this.compact?1.2:1.6));this.renderer.outputColorSpace=T.SRGBColorSpace;this.renderer.toneMapping=T.ACESFilmicToneMapping;this.renderer.toneMappingExposure=1;this.renderer.shadowMap.enabled=!this.compact;this.renderer.shadowMap.type=T.PCFSoftShadowMap;this.scene=new T.Scene();this.scene.background=new T.Color(0xf0eadc);this.scene.fog=new T.Fog(0xf0eadc,45,95);this.camera=new T.PerspectiveCamera(48,1,.1,150);this.scene.add(new T.HemisphereLight(0xfff4db,0x9aaa88,1.9));this.sun=new T.DirectionalLight(0xffedca,2.5);this.sun.position.set(-13,24,14);this.sun.castShadow=true;this.sun.shadow.mapSize.set(1024,1024);Object.assign(this.sun.shadow.camera,{left:-19,right:19,top:19,bottom:-19});this.sun.shadow.normalBias=.04;this.scene.add(this.sun);
 this.arena=new T.Group();this.scene.add(this.arena);this.actors=new T.Group();this.scene.add(this.actors);this.buildArena();this.cats=new Map();for(const id of ['monaka','ohagi','daifuku']){const model=createCat(id);this.cats.set(id,model);this.actors.add(model);}this.mouseModels=new Map();this.bonusModels=new Map();this.effects=[];this.preview=new T.Group();this.preview.visible=false;this.scene.add(this.preview);this.previewCats=new Map();mesh(this.preview,cylinder,0xead3a7,0,-.13,0,1.75,.23,1.75);this.marker=mesh(this.actors,cone,new T.MeshBasicMaterial({color:0xef9660}),0,1.3,0,.16,.28,.16);this.marker.rotation.z=Math.PI;this.aura=new T.Mesh(new T.RingGeometry(.85,1.05,36),new T.MeshBasicMaterial({color:0xffe6a3,transparent:true,opacity:.8,side:T.DoubleSide}));this.aura.rotation.x=-Math.PI/2;this.actors.add(this.aura);this.wave=new T.Mesh(new T.RingGeometry(.95,1,48),new T.MeshBasicMaterial({color:0xefffc4,transparent:true,opacity:0,side:T.DoubleSide}));this.wave.rotation.x=-Math.PI/2;this.actors.add(this.wave);this.waveLife=0;this.yaw=0;this.pitch=.97;this.zoom=1;this.overview=false;this.inspect=false;this.previewYaw=0;this.previewPitch=.12;this.snap=true;this.target=new T.Vector3();this.resize();new ResizeObserver(()=>this.resize()).observe(canvas);
 }
 resize(){const r=this.canvas.getBoundingClientRect();if(r.width&&r.height){this.renderer.setSize(r.width,r.height,false);this.camera.aspect=r.width/r.height;this.camera.updateProjectionMatrix();}}
 buildArena(){box(this.arena,0xf5f0e5,0,-.8,0,180,.1,180);box(this.arena,0xc7b795,0,-.39,0,24.8,.72,24.8);this.grassMat=mat(0xb8d898).clone();box(this.arena,this.grassMat,0,-.04,0,24,.12,24);for(const x of [-11.9,11.9])for(let z=-11.4;z<=11.4;z+=.8)ball(this.arena,0x8ead79,x,.35,z,.42,.42,.44);for(const z of [-11.9,11.9])for(let x=-11.4;x<=11.4;x+=.8)ball(this.arena,0x8ead79,x,.35,z,.42,.42,.44);
 for(const q of ARENA.obstacles){box(this.arena,0xbc9765,q.x+q.w/2,q.h/2,q.z+q.d/2,q.w,q.h,q.d);box(this.arena,0xe6c58e,q.x+q.w/2,q.h+.04,q.z+q.d/2,q.w+.1,.08,q.d+.1);for(let j=0;j<3;j++)box(this.arena,0xa98458,q.x+.3+j*.5,q.h*.5,q.z+q.d+.025,.055,q.h*.75,.05);}
 for(let i=0;i<32;i++){const a=i*.84,x=Math.sin(a)*(9.7+(i%2)*.6),z=Math.cos(a)*(9.7+(i%2)*.6);ball(this.arena,0x93b784,x,.08,z,.17,.1,.18);for(let j=0;j<4;j++)ball(this.arena,[0xf6c3ae,0xf4d781,0xe0d4ef][i%3],x+Math.sin(j*1.57)*.12,.18,z+Math.cos(j*1.57)*.12,.09,.06,.09);}
 for(const [x,z] of [[-10,-10],[10,-10],[-10,10],[10,10]]){mesh(this.arena,cylinder,0xae8f69,x,.8,z,.18,1.6,.18);for(let j=0;j<4;j++)ball(this.arena,[0x9fc18a,0xb5cc90][j%2],x+Math.sin(j*2)*.45,1.7+(j%2)*.28,z+Math.cos(j*2)*.4,.8,.85,.8);}
 for(let i=0;i<24;i++){const a=i*2.4,x=Math.sin(a)*8.5,z=Math.cos(a)*8.5;ball(this.arena,0xd9dfb5,x,.015,z,.38,.02,.29);}batch(this.arena);
 }
 makeMouse(gold){const g=new T.Group(),fur=gold?0xe0b550:0x8e96a0,belly=gold?0xffe6a0:0xe6dfd6;ball(g,fur,0,.27,-.06,.25,.24,.39);ball(g,fur,0,.34,.28,.23,.22,.25);for(const x of [-.20,.20]){ball(g,fur,x,.56,.21,.16,.17,.07);ball(g,gold?0xf3d6a2:0xe8b6b4,x,.56,.264,.105,.11,.025);ball(g,0x242c36,x*.65,.39,.47,.035,.048,.024);}ball(g,belly,0,.21,.11,.18,.14,.28);ball(g,0xe89a9c,0,.29,.53,.047,.04,.04);for(const x of [-.16,.16])for(const z of [-.25,.22])ball(g,0xd9b6ac,x,.06,z,.075,.055,.11);const tail=new T.Mesh(new T.TorusGeometry(.23,.027,5,14,Math.PI*1.5),mat(gold?0xf1d79b:0xd6aca8));tail.position.set(.17,.12,-.51);tail.rotation.x=Math.PI/2;g.add(tail);g.userData.tail=tail;if(gold){const tag=label('+50','#ab7b25',.75);tag.position.set(0,.98,0);g.add(tag);}this.actors.add(g);return g;}
 makeBonus(kind){const g=new T.Group(),info=BONUS[kind];mesh(g,cylinder,0xfff4d5,0,.12,0,.40,.17,.40);if(kind==='cheese'){const c=mesh(g,cone,info.color,0,.52,0,.36,.45,.36);c.rotation.z=Math.PI/2;for(const x of [-.13,.12])ball(g,0xcfa448,x,.5,.23,.055,.055,.03);}else if(kind==='star'){const s=label('★','#d7a12b',1.05);s.position.y=.55;g.add(s);}else if(kind==='clock'){const s=label('⏱','#5a9dad',.95);s.position.y=.55;g.add(s);}else{ball(g,info.color,0,.46,0,.34,.34,.34);const s=label(kind==='double'?'×2':kind==='snow'?'❄':'⚡','#5b627a',.75);s.position.set(0,.55,.2);g.add(s);}const ring=new T.Mesh(new T.TorusGeometry(.44,.025,5,28),mat(info.color));ring.rotation.x=Math.PI/2;ring.position.y=.12;g.add(ring);this.actors.add(g);return g;}
 burst(x,z,gold=false){for(let i=0;i<9;i++){const o=ball(this.actors,gold?0xffd16b:[0xffdf82,0xf2b9b3,0xe0f0b2][i%3],x,.5,z,.075,.075,.075);const a=i/9*Math.PI*2;this.effects.push({o,life:.65,vx:Math.sin(a)*2.2,vz:Math.cos(a)*2.2,vy:2.8});}}
 meowEffect(x,z){this.waveLife=.65;this.wave.position.set(x,.09,z);}
 rotate(x,y=0){if(this.inspect){this.previewYaw+=x;this.previewPitch=Math.max(-.1,Math.min(.65,this.previewPitch+y));}else{this.yaw+=x;this.pitch=Math.max(.55,Math.min(1.22,this.pitch+y));}}
 previewPersonality(id){const r=findCat(id).preview;this.previewReaction={motion:r.motion,duration:r.duration,remaining:r.duration};this.previewYaw=0;}
 setInspect(on,id){this.inspect=on;this.snap=true;this.previewYaw=0;this.previewReaction=null;if(on&&!this.previewCats.has(id)){const c=createCat(id);this.preview.add(c);this.previewCats.set(id,c);}}
 draw(game,time,dt){this.arena.visible=!this.inspect;this.actors.visible=!this.inspect;this.preview.visible=this.inspect;
 if(this.inspect){if(!this.previewCats.has(game.selectedCat))this.setInspect(true,game.selectedCat);if(this.previewReaction)this.previewReaction.remaining=Math.max(0,this.previewReaction.remaining-dt);for(const [id,c] of this.previewCats){c.visible=id===game.selectedCat;if(c.visible){animateCat(c,time,false,false,this.previewReaction||{});c.rotation.y=this.previewYaw;}}const d=4.6*this.zoom;this.camera.position.set(0,1.35+Math.sin(this.previewPitch)*d,Math.cos(this.previewPitch)*d);this.camera.lookAt(0,.95,0);this.renderer.render(this.scene,this.camera);return;}
 this.waveLife=Math.max(0,this.waveLife-dt);this.wave.visible=this.waveLife>0;this.wave.material.opacity=this.waveLife/.65*.85;this.wave.scale.setScalar((1-this.waveLife/.65)*5+.1);
 const p=game.player;if(this.lastLevel!==game.level){this.lastLevel=game.level;this.grassMat.color.setHex(game.stage.color);this.sun.color.setHex(game.level===4?0xffd3a5:game.level===5?0xeee3ff:0xffedca);}
 for(const [id,c] of this.cats){c.visible=id===game.selectedCat;if(!c.visible)continue;const pose=animateCat(c,time,p.moving&&game.mode==='playing',false,game.mode==='playing'?{motion:game.flairMotion,duration:game.flairDuration,remaining:game.flairTimer}:{});c.scale.setScalar(.76);c.position.set(p.x,p.y+pose.lift,p.z);c.rotation.set((game.pounceTimer>0?-.18:0)+pose.pitch,p.angle,pose.roll);}
 const ids=new Set();for(const m of game.mice){ids.add(m.id);let model=this.mouseModels.get(m.id);if(!model){model=this.makeMouse(m.gold);this.mouseModels.set(m.id,model);}model.visible=m.active||m.respawn>.75;model.position.set(m.x,.035+Math.abs(Math.sin(time*(game.slow>0?4:14)+m.id))*.035,m.z);model.rotation.y=m.angle;model.scale.setScalar(m.active?1:Math.max(0,(m.respawn-.75)/.2));model.userData.tail.rotation.z=Math.sin(time*10+m.id)*.18;}for(const [id,m] of this.mouseModels)if(!ids.has(id))m.visible=false;
 const live=new Set();for(const b of game.bonuses){if(!b.active)continue;live.add(b.id);let model=this.bonusModels.get(b.id);if(!model){model=this.makeBonus(b.kind);this.bonusModels.set(b.id,model);}model.visible=true;model.position.set(b.x,Math.sin(time*2+b.x)*.08,b.z);model.rotation.y=time*.5;}for(const [id,m] of this.bonusModels)if(!live.has(id)){this.actors.remove(m);m.traverse(o=>{if(o.isSprite){o.material.map?.dispose();o.material.dispose();}});this.bonusModels.delete(id);}
 for(const e of this.effects){e.life-=dt;e.vy-=dt*7;e.o.position.x+=e.vx*dt;e.o.position.z+=e.vz*dt;e.o.position.y+=e.vy*dt;e.o.scale.setScalar(Math.max(0,e.life)*.14);}this.effects=this.effects.filter(e=>{if(e.life>0)return true;this.actors.remove(e.o);return false;});
 const near=game.nearestMouse;this.marker.visible=!!near&&game.mode==='playing';if(near)this.marker.position.set(near.x,1.15+Math.sin(time*5)*.10,near.z);this.aura.visible=game.pounceTimer>0||game.boost>0||game.double>0;this.aura.position.set(p.x,p.y+.06,p.z);this.aura.scale.setScalar(game.pounceTimer>0?1.4:1);
 let target=new T.Vector3(p.x,.65,p.z),position;if(this.overview){target.set(0,0,0);const r=this.camera.aspect<1?34:25;position=new T.Vector3(Math.sin(this.yaw)*r*.25,r,Math.cos(this.yaw)*r*.75);}else{const r=(this.camera.aspect<1?13:11.4)*this.zoom*(this.camera.aspect>2?.8:1),h=Math.cos(this.pitch)*r;position=new T.Vector3(p.x+Math.sin(this.yaw)*h,.65+Math.sin(this.pitch)*r,p.z+Math.cos(this.yaw)*h);}const k=this.snap?1:1-Math.exp(-dt*9);this.camera.position.lerp(position,k);this.target.lerp(target,k);this.camera.lookAt(this.target);this.snap=false;this.renderer.render(this.scene,this.camera);
 }
}
